const nights = Number($fromAI('nights', 1));
const adults = Number($fromAI('adults', 1));
const hotelName = $fromAI('hotel_name', '');
const singlePerNight = Number($fromAI('single_per_night_usd', 0));
const doublePerNight = Number($fromAI('double_per_night_usd', 0));
const roomsSingle = Number($fromAI('rooms_single', 0));
const roomsDouble = Number($fromAI('rooms_double', 0));

if ((roomsSingle > 0 && singlePerNight === 0) || (roomsDouble > 0 && doublePerNight === 0)) {
  return JSON.stringify({
    hotel_name: hotelName,
    error: "No pricing available for requested dates",
    grand_total: 0
  });
}

const singleTotal = singlePerNight * nights * roomsSingle;
const doubleTotal = doublePerNight * nights * roomsDouble;
const hotelTotal = Math.round(singleTotal + doubleTotal);

const extraBedPrice = Number($fromAI('extra_bed_price_usd', 0));
const extraBedsCount = Number($fromAI('extra_beds_count', 0));
const extraBedTotal = Math.round(extraBedPrice * extraBedsCount * nights);

const tourDays = Math.max(1, nights - 2);
const transferPrice = Number($fromAI('transfer_price_usd', 0));
const rentPrice = Number($fromAI('rent_price_usd', 0));
const guidePrice = Number($fromAI('guide_price_usd', 0));
const simPrice = Number($fromAI('sim_price_usd', 0));

const transferTotal = Math.round(transferPrice * 2);
const rentTotal = Math.round(rentPrice * tourDays);
const guideTotal = Math.round(guidePrice * tourDays);
const simTotal = Math.round(simPrice * adults);

const grandTotal = hotelTotal + extraBedTotal + transferTotal + rentTotal + guideTotal + simTotal;

return JSON.stringify({
  hotel_name: hotelName,
  nights: nights,
  tour_days: tourDays,
  breakdown: {
    hotel: hotelTotal,
    extra_beds: extraBedTotal,
    transfer: transferTotal,
    rent: rentTotal,
    guide: guideTotal,
    sim: simTotal
  },
  grand_total: grandTotal
});

const items = $input.all();
let inputData = items[0]?.json?.body || items[0]?.json || items[0];

const {
  nights, adults = 0, children_count = 0, hotel_name, checkin_date,
  single_weekday_usd = 0, single_weekend_usd = 0,
  double_weekday_usd = 0, double_weekend_usd = 0,
  rooms_single = 0, rooms_double = 0,
  extra_bed_price_usd = 0, extra_beds_count = 0,
  transfer_price_usd = 0, rent_price_usd = 0,
  guide_price_usd = 0, sim_price_usd = 0
} = inputData || {};

// ❌ Do NOT throw errors in AI Agent tools
if (!nights || !hotel_name || !checkin_date) {
  return [
    {
      json: {
        response: "❌ Missing required data (nights, hotel_name, or checkin_date).",
        data: {
          error: true,
          received: { nights, hotel_name, checkin_date }
        }
      }
    }
  ];
}

const checkinDateObj = new Date(checkin_date);
let hotelCost = 0;

for (let i = 0; i < nights; i++) {
  const currentDate = new Date(checkinDateObj);
  currentDate.setDate(currentDate.getDate() + i);
  const dayOfWeek = currentDate.getDay(); // 0=Sun ... 6=Sat
  const isWeekday = [2, 3, 4].includes(dayOfWeek); // Tue, Wed, Thu

  if (rooms_single > 0) {
    hotelCost += rooms_single * (isWeekday ? single_weekday_usd : single_weekend_usd);
  }

  if (rooms_double > 0) {
    hotelCost += rooms_double * (isWeekday ? double_weekday_usd : double_weekend_usd);
  }
}

const tourDays = Math.max(0, nights - 2);
const extraBedsCost = extra_bed_price_usd * extra_beds_count * nights;
const transferCost = transfer_price_usd;
const rentCost = rent_price_usd * tourDays;
const guideCost = guide_price_usd * tourDays;
const simCost = sim_price_usd * adults;

const grandTotal = hotelCost + extraBedsCost + transferCost + rentCost + guideCost + simCost;

const rounded = (n) => Math.round(n * 100) / 100;

return [
  {
    json: {
      response: `💰 Total package price for ${hotel_name} is ${rounded(grandTotal)} USD`,
      data: {
        hotel_name,
        nights,
        adults,
        children_count,
        breakdown: {
          hotel: rounded(hotelCost),
          extra_beds: rounded(extraBedsCost),
          transfer: rounded(transferCost),
          rent: rounded(rentCost),
          guide: rounded(guideCost),
          sim: rounded(simCost)
        },
        grand_total: rounded(grandTotal)
      }
    }
  }
];
